body='''/** Addresses are compared without regard to letter case. */
function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

/**
 * Bulk invite. The seat quota is checked once for the whole batch — inviting
 * five people into a plan with three free seats must fail as a batch rather
 * than half-succeeding — and the rate limit is charged per invite.
 */
export async function inviteMembers(
  actor: Actor,
  input: InviteMembersInput,
): Promise<readonly Invitation[]> {
  return issueInvitations(actor, input.orgId, input.invites, null);
}

/**
 * The one path that mints invitations. Every check runs before the first row
 * is written, so a refused batch creates nothing. `replacing` names an
 * invitation this batch supersedes (a re-send): it neither blocks its own
 * address nor holds a seat, and it is withdrawn once the batch is cleared.
 */
async function issueInvitations(
  actor: Actor,
  orgId: OrgId,
  invites: readonly { email: string; role: Role }[],
  replacing: Invitation | null,
): Promise<readonly Invitation[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "member:invite", orgResource(orgId));

  const verdict = await consumeRateLimit(orgId, INVITE_BUCKET, invites.length);
  if (!verdict.allowed) {
    throw new Error(
      `Invite rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  if (org.archivedAt !== null) {
    throw new Error("That workspace has been deleted");
  }

  const memberEmails = new Set(await memberRepo.listMemberEmails(orgId));
  const pendingEmails = new Set(
    await invitationRepo.listPendingInvitationEmails(
      orgId,
      replacing?.id ?? null,
    ),
  );
  const seen = new Set<string>();

  for (const invite of invites) {
    const email = normalizeEmail(invite.email);
    if (seen.has(email)) {
      throw new Error(`${invite.email} is named more than once in this batch`);
    }
    seen.add(email);

    if (memberEmails.has(email)) {
      throw new Error(`${invite.email} is already a member of this workspace`);
    }
    if (pendingEmails.has(email)) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }

  const replacedIsPending =
    replacing !== null &&
    replacing.acceptedAt === null &&
    replacing.revokedAt === null &&
    replacing.expiresAt > toIsoTimestamp(new Date());

  const seatsUsed =
    (await memberRepo.countActiveMembers(orgId)) +
    (await invitationRepo.countPendingInvitations(orgId)) -
    (replacedIsPending ? 1 : 0);

  if (wouldExceedLimit(org.plan, "seats", seatsUsed, invites.length)) {
    const limits = getPlanLimits(org.plan);
    throw new Error(
      `Plan ${org.plan} includes ${limits.seats} seats and ${seatsUsed} are taken`,
    );
  }

  if (replacing !== null && replacing.revokedAt === null) {
    await invitationRepo.revokeInvitation(orgId, replacing.id);
  }

  const invitations: Invitation[] = [];

  for (const invite of invites) {
    const token = randomToken(32);
    const invitation = await invitationRepo.insertInvitation(
      orgId,
      {
        orgId,
        email: invite.email,
        // The stored column accepts every role; the invitable subset is
        // enforced by the input schema, and a re-send copies the original.
        role: invite.role as InviteMemberInput["role"],
        expiresInDays: DEFAULT_EXPIRY_DAYS,
      },
      actor.userId,
      hashToken(token),
    );

    invitations.push(invitation);

    await emit("member.invited", {
      orgId,
      actorId: actor.userId,
      occurredAt: invitation.createdAt,
      email: invite.email,
      role: invite.role,
    });
  }

  return invitations;
}

/**
 * Accepting is authorised by two things together: the token, and the signed-in
 * account owning the address the invitation was sent to. There is no `Actor`
 * to scope against, so every check comes off the stored rows.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (org === null || org.archivedAt !== null) {
    throw new Error("That invitation is for a workspace that no longer exists");
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (normalizeEmail(user.email) !== normalizeEmail(invitation.email)) {
    throw new Error(
      "That invitation was sent to a different email address; sign in with the invited account",
    );
  }

  const acceptedAt = toIsoTimestamp(new Date());
  const existing = await memberRepo.findMemberIncludingRemoved(
    invitation.orgId,
    userId,
  );

  // Already a current member: the invitation is used up, nothing else moves.
  if (existing !== null && existing.archivedAt === null) {
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      acceptedAt,
    );
    return existing;
  }

  // A former member gets their earlier membership back rather than a second
  // row; anyone else gets a new one. Either way they are active at once.
  const member =
    existing !== null
      ? await memberRepo.restoreMember(
          invitation.orgId,
          existing.id,
          invitation.role,
          invitation.invitedBy,
          acceptedAt,
        )
      : await memberRepo.insertMember(
          invitation.orgId,
          userId,
          invitation.role,
          invitation.invitedBy,
        );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  await usageRepo.syncSeats(invitation.orgId);

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const invitation = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.revokedAt !== null) return invitation;

  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing mints a new row: the original is withdrawn and replaced so the
 * audit trail keeps both, and the old link stops working immediately. The new
 * invitation goes to the same address with the same role and a fresh validity
 * window. An expired invitation can be re-sent — that is the usual reason.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );

  if (previous.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (previous.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }

  const [invitation] = await issueInvitations(
    actor,
    actor.orgId,
    [{ email: previous.email, role: previous.role }],
    previous,
  );

  if (!invitation) throw new Error("Invitation was not created");
  return invitation;
}
